def get_all_runs_with_failures(self) -> pd.DataFrame:
    """Return a DataFrame of all runs enriched with failure reasons.

    Uses analysis_report.json when available. Falls back to marking runs
    without metrics as 'Unknown failure'.
    """
    report = self.get_analysis_report()
    if report is not None:
        return build_all_runs_table(report)

    # Fallback: use get_all_runs and infer failure status from has_metrics
    runs_df = self.get_all_runs()
    if runs_df.empty:
        return runs_df

    runs_df["has_output"] = runs_df["has_metrics"]
    runs_df["failure_reason"] = runs_df.apply(
        lambda r: None if r["has_metrics"] else "Unknown", axis=1
    )
