    return runs_df

def get_error_breakdown(self) -> pd.DataFrame:
    """Per-run error type counts from analysis report.

    Returns DataFrame with columns: run_id, model, error_type, count.
    """
    report = self.get_analysis_report()
    if report is None:
        return pd.DataFrame(columns=["run_id", "model", "error_type", "count"])

    rows = []
    for run in report.get("runs", []):
        run_id = run.get("run_id", "")
        model = run.get("llm_model", "")
        problems = run.get("problems", [])
        # Count each problem type
        type_counts: dict[str, int] = {}
        for p in problems:
            ptype = p.get("name", p.get("problem_id", "unknown"))
            type_counts[ptype] = type_counts.get(ptype, 0) + 1
        for error_type, count in type_counts.items():
            rows.append({
                "run_id": run_id,
                "model": model,
                "error_type": error_type,
                "count": count,
            })

    return pd.DataFrame(rows) if rows else pd.DataFrame(
        columns=["run_id", "model", "error_type", "count"]
    )

def get_column_errors(self) -> pd.DataFrame:
    """Per-column per-run error counts from metrics.

    Returns DataFrame with columns: run_id, model, column_name,
    hallucinations, omissions, accuracy.
    """
    rows = []
    with self._cache_lock:
        index_copy = dict(self._run_index)

    for run_id in index_copy:
        metrics = self.get_run_metrics(run_id)
        if metrics is None:
            continue
        model = metrics.get("metadata", {}).get("llm_model", "")
        col_vals = metrics.get("column_values", {})
        for col_name, col_data in col_vals.items():
            rows.append({
                "run_id": run_id,
                "model": model,
                "column_name": col_name,
                "hallucinations": col_data.get("hallucinations", 0),
                "omissions": col_data.get("omissions", 0),
                "accuracy": col_data.get("accuracy_excl_empty"),
            })

    return pd.DataFrame(rows) if rows else pd.DataFrame(
        columns=["run_id", "model", "column_name", "hallucinations",
                 "omissions", "accuracy"]
    )

