"""Failure Analysis tab — success/failure heatmap, failure distribution, sunburst."""

import dash_bootstrap_components as dbc
from dash import dcc, html

from evaluation.visualization.plots import (
    plot_failure_distribution,
    plot_failure_sunburst,
    plot_success_failure_heatmap,
)


def render_failure_analysis(data_loader) -> html.Div:
    """Render the Failure Analysis tab."""
    all_runs = data_loader.get_all_runs_with_failures()

    if all_runs is None or len(all_runs) == 0:
        return html.Div([
            dbc.Button(
                "Refresh Data", id="refresh-failure", color="primary",
                size="sm", className="mb-3",
            ),
            html.P(
                "No run data available. Run experiments or ensure an "
                "analysis_report.json exists.",
                className="text-muted text-center my-5",
            ),
        ])

    n_total = len(all_runs)
    n_success = int(all_runs["has_output"].sum()) if "has_output" in all_runs.columns else 0
    n_failed = n_total - n_success

    components = [
        dbc.Button(
            "Refresh Data", id="refresh-failure", color="primary",
            size="sm", className="mb-3 me-2",
        ),
        dbc.Alert(
            f"{n_total} runs total: {n_success} successful, {n_failed} failed",
            color="info" if n_failed == 0 else "warning",
            className="mb-3",
        ),
    ]

    # Success/failure heatmap
    try:
        fig_heatmap = plot_success_failure_heatmap(
            all_runs, row_col="model", col_col="context", backend="plotly",
        )
        components.append(dcc.Graph(id="failure-heatmap", figure=fig_heatmap))
    except Exception as e:
        components.append(dbc.Alert(f"Cannot render heatmap: {e}", color="secondary"))

    # Failure distribution bar + sunburst side by side
    if n_failed > 0:
        row_children = []

        try:
            fig_dist = plot_failure_distribution(all_runs, backend="plotly")
            row_children.append(
