    logger.info(f"Starting dashboard on http://0.0.0.0:{args.port}")
    logger.info(f"Access via: ssh -L {args.port}:localhost:{args.port} <this-host>")

    app.run(host="0.0.0.0", port=args.port, debug=False)


if __name__ == "__main__":
